import java.util.StringTokenizer;
public class Tools {
    public static void main(String[] args) {
        StringTokenizer st = new StringTokenizer("Java is fun to learn");
        System.out.println(st.countTokens());        // 5
        st.nextToken();
        System.out.println(st.countTokens());        // 4 (tokens LEFT)

        StringTokenizer csv = new StringTokenizer("apple,banana;orange", ",;");
        while (csv.hasMoreTokens()) System.out.println(csv.nextToken());

        System.out.println(Math.pow(2, 3));          // 8.0
        System.out.println(Math.sqrt(49));           // 7.0
        System.out.println(Math.round(4.6));         // 5
        System.out.println(Math.ceil(4.1) + " " + Math.floor(4.9)); // 5.0 4.0
        System.out.println(Math.abs(-15) + " " + Math.max(10, 25)); // 15 25
        int dice = (int)(Math.random() * 6) + 1;     // 1..6
